input.command:
node --input-type=module - <<'EOF'
import { payoutCents } from './impl.ts';
const history = { merchantId: 'm1', payouts: [] };
const payout = (availableCents, ageDays, riskCleared, pendingCents = 99999) => payoutCents({ id: 'b1', merchantId: 'm1', availableCents, pendingCents, ageDays, riskCleared }, history);
const cases = [
  ['new reserve', payout(10001, 6, false), 0],
  ['week-old reserve', payout(10001, 7, false), 5000],
  ['cleared reserve', payout(10001, 0, true), 10001],
  ['negative balance', payout(-25, 20, true), 0],
  ['fractional balance', payout(100.9, 20, false), 50],
];
for (const [name, actual, expected] of cases) {
  if (actual !== expected) throw new Error(`${name}: expected ${expected}, got ${actual}`);
  console.log(`${name}: ${actual}`);
}
EOF
